using System.IO;using System.Linq;using System.Reflection;using UnityEngine;using UnityEditor;using UnityEngine.SceneManagement;
[InitializeOnLoad]public static class CanalShoreAudit{static CanalShoreAudit(){EditorApplication.update+=Poll;}static void Poll(){if(EditorApplication.isCompiling||!File.Exists("CanalShoreAudit.request"))return;File.Delete("CanalShoreAudit.request");var s=SceneManager.GetSceneByPath("Assets/Editor/DayNightBackups/Gangstar Final Env.unity");var roads=s.GetRootGameObjects().Single(g=>g.name=="Track Roads");var lines=new System.Collections.Generic.List<string>();foreach(var f in roads.GetComponentsInChildren<MeshFilter>().Where(f=>f.name.ToLower().Contains("canal"))){lines.Add(f.name+" "+AssetDatabase.GetAssetPath(f.sharedMesh)+" "+f.GetComponent<Renderer>().bounds);var data=typeof(FinalPNGCityDetails).GetMethod("Read",BindingFlags.Static|BindingFlags.NonPublic).Invoke(null,new object[]{f.sharedMesh});var p=(Vector3[])data.GetType().GetField("p").GetValue(data);File.WriteAllLines("FinalEnvironmentRoadReview/"+f.name+" ShorePoints.csv",p.Select(v=>f.transform.TransformPoint(v)).Select(v=>v.x.ToString("R",System.Globalization.CultureInfo.InvariantCulture)+","+v.y.ToString("R",System.Globalization.CultureInfo.InvariantCulture)+","+v.z.ToString("R",System.Globalization.CultureInfo.InvariantCulture)));}File.WriteAllLines("FinalEnvironmentRoadReview/CanalShoreAudit.txt",lines);}}
